 id:'s1-yellow-bourbon',title:['Màu vàng trước khi rang','Yellow before roasting'],kind:'bean',item:['Brazil · Yellow Bourbon','Brazil · Yellow Bourbon'],place:['Brazil','Brazil'],color:'#cbb465',sources:['bourbon','wcr'],
 guest:{name:'Kwame Mensah',origin:['Ghana · Châu Phi','Ghana · Africa'],portrait:2,line:['“Yellow nghĩa là rang nhạt hơn túi Bourbon hôm trước à?”','“Does Yellow mean a lighter roast than the other Bourbon bag?”']},
 arrival:['Chủ quán đặt hai hình quả cà phê cạnh một hạt rang. “Hôm nay thử nhìn lại thứ đã biến mất trước khi hạt vào túi: màu của quả.”','The owner places two cherry drawings beside a roasted seed. “Today let’s look at something that disappears before coffee reaches the bag: the fruit’s color.”'],
 acquisition:['“Tôi ghé một buổi giới thiệu cà phê Brazil, định chỉ xin mẫu nhỏ. Rốt cuộc thứ khiến mình quay lại bàn là tấm ảnh quả chín vàng cạnh túi Yellow Bourbon. Tôi xin phép giữ bản ảnh giới thiệu, vì chụp mỗi hạt rang thì mất câu chuyện này.”','“I stopped by a Brazilian coffee introduction intending to request a small sample. A photo of yellow cherries beside Yellow Bourbon brought me back to the table. I asked to keep the introductory picture: a roasted-seed photo would miss this story.”'],
 story:[['“Cà phê có những giống và biến thể có màu quả chín khác nhau. Chữ Yellow trong tên này nói đến quả vàng, không đưa cho mình một thang đo mức rang. Hạt trong túi đã đi qua nhiều bước sau khi rời cây.”','“Coffee varieties and variants can have different ripe-cherry colors. Yellow in this name refers to yellow fruit, not a roast-level measurement. The seed has passed through many steps after leaving the tree.”'],['“Mình đã gặp Bourbon ở ngăn Guatemala. Quay lại tên quen trong một bối cảnh mới giúp tôi nhớ thế giới cà phê không phải mỗi nước một giống, mỗi giống một vị. Chiếc tủ đang bắt đầu nối các ngăn với nhau.”','“We met Bourbon in the Guatemala drawer. Meeting a familiar name in a new setting reminds us that coffee isn’t one variety per country or one flavor per variety. The drawers are beginning to connect.”']],
 answer:['“Không. Muốn biết mức rang thì cần thông tin rang riêng. Ảnh quả và màu hạt rang trả lời những câu hỏi khác nhau.”','“No. Roast information needs a separate record. A cherry photo and roasted-seed color answer different questions.”'],
 facts:[['Yellow trong tên này chỉ màu quả, không phải mức rang.','Yellow in this name refers to fruit color, not roast level.'],['Cần ghi mức rang và thông tin lô riêng.','Record roast and lot information separately.'],['Cùng tên giống có thể được trồng tại nhiều nơi.','A variety name can occur in more than one growing country.']],
 invitation:['“Bạn muốn tìm đúng trường thông tin, hay giữ màu quả vàng trong tấm thẻ? Không cần đoán độ ngọt từ màu nhé.”','“Find the right information field, or keep the yellow fruit on a card? No guessing sweetness from color.”'],
 ending:['Chủ quán nối hai ngăn Bourbon bằng một sợi chỉ nhỏ. “Một sợi dây để nhớ điều có liên hệ; không phải để buộc hai ly phải giống nhau.”','The owner connects the Bourbon drawers with a little thread. “A thread to remember a relationship, not to force two cups to be identical.”'],
 teaser:['Cùng tác giả Hoffmann, nhưng một ly nhỏ không chỉ là chia đôi mọi thao tác.','The same author, but one small cup is more than halving every action.'],modes:['clue','postcard','memory'],
 quiz:{question:['Yellow trong tên hôm nay cho biết điều gì?','What does Yellow in today’s name describe?'],choices:[['Thời gian rang','Roast duration'],['Màu quả','Cherry color'],['Lượng đường trong ly','Sugar amount in the cup']],correct:1,explanation:['Đó là màu quả, không phải phép đo mức rang hay đường.','It describes fruit color, not a roast or sugar measurement.']},
 order:[['Quan sát màu quả','Observe cherry color'],['Đọc riêng hồ sơ giống','Read the variety record separately'],['Đọc riêng thông tin rang','Read roast information separately']],pairs:[['Quả vàng','Yellow cherry'],['Hạt rang','Roasted seed'],['Hồ sơ rang','Roast record']],symbols:['●','◐','▤']
